{
  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["case_input", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "llm",
      "param": {
        "system": "You are a Python code validator and formatter. Your task is to:

1. Check if the provided code has correct Python syntax
2. Verify the code structure and format
3. Fix any obvious syntax errors or formatting issues
4. Ensure the code is executable
5. If there are major issues that cannot be automatically fixed, return the original code with error comments

Return only the validated/cleaned Python code without any explanations or additional text.",
        "user": "Please validate and format the following Python code:

{{#1.case_input#}}"
      }
    },
    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [
          ["python_code", ["text", "2"]]
        ],
        "outputs": [
          ["result", "string"]
        ],
        "code": "def main(python_code: str) -> str:
	try:
		# Create a local namespace for execution
		local_namespace = {}

		# Execute the code
		exec(python_code, globals(), local_namespace)

		# Collect output from the execution
		output_parts = []

		# Check for variables that might contain results
		for key, value in local_namespace.items():
			if not key.startswith('_') and key != 'python_code':
				output_parts.append(f"{key} = {repr(value)}")

		# If no variables found, check if code printed anything
		if not output_parts:
			# Try to capture print output by executing with redirected stdout
			import io
			import sys

			old_stdout = sys.stdout
			sys.stdout = captured_output = io.StringIO()

			try:
				exec(python_code, globals(), local_namespace)
				captured = captured_output.getvalue()
				if captured.strip():
					output_parts.append(f"Output: {captured.strip()}")
			finally:
				sys.stdout = old_stdout

		# Return execution result
		if output_parts:
			return "\n".join(output_parts)
		else:
			return "Code executed successfully (no output captured)"

	except Exception as e:
		return f"Execution error: {str(e)}""
      }
    },
    {
      "id": "4",
      "type": "end",
      "param": {
        "outputs": [
          ["python_code", ["text", "2"]],
          ["result", ["result", "3"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"],
    ["3", 0, "4"]
  ]
}

