        "code": "def main(question_text, subject, question_type, difficulty, answer, user_answer, explanation):\n\t# Check if inputs are lists (multiple questions) or single values\n\tif isinstance(question_text, list):\n\t\t# Handle multiple questions\n\t\terror_notebook = []\n\t\tfor i in range(len(question_text)):\n\t\t\tquestion_data = {\n\t\t\t\t'question_text': question_text[i] if i < len(question_text) else '',\n\t\t\t\t'subject': subject[i] if i < len(subject) else '',\n\t\t\t\t'question_type': question_type[i] if i < len(question_type) else '',\n\t\t\t\t'difficulty': difficulty[i] if i < len(difficulty) else '',\n\t\t\t\t'answer': answer[i] if i < len(answer) else '',\n\t\t\t\t'user_answer': user_answer[i] if i < len(user_answer) else '',\n\t\t\t\t'explanation': explanation[i] if i < len(explanation) else ''\n\t\t\t}\n\t\t\terror_notebook.append(question_data)\n\telse:\n\t\t# Handle single question\n\t\terror_notebook = [{\n\t\t\t'question_text': question_text,\n\t\t\t'subject': subject,\n\t\t\t'question_type': question_type,\n\t\t\t'difficulty': difficulty,\n\t\t\t'answer': answer,\n\t\t\t'user_answer': user_answer,\n\t\t\t'explanation': explanation\n\t\t}]\n\t\n\t# Convert to JSON string\n\timport json\n\treturn {\n\t\t'result': json.dumps(error_notebook, ensure_ascii=False, indent=2)\n\t}"
