        "code": "def main(api_response: str, api_url: str):
	import json
	import requests

	def get_recursive_contents(url, depth=0, max_depth=10):
		if depth > max_depth:
			return []

		try:
			response = requests.get(url)
			response.raise_for_status()
			contents = response.json()

			if isinstance(contents, dict) and 'message' in contents:
				return [f"Error: {contents['message']}"]

			result = []
			for item in contents:
				if item['type'] == 'file':
					result.append(f"{'  ' * depth}📄 {item['name']}")
				elif item['type'] == 'dir':
					result.append(f"{'  ' * depth}📁 {item['name']}/")
					# Recursively get directory contents
					sub_contents = get_recursive_contents(item['url'], depth + 1, max_depth)
					result.extend(sub_contents)
				elif item['type'] == 'submodule':
					result.append(f"{'  ' * depth}🔗 {item['name']} (submodule)")

			return result
		except Exception as e:
			return [f"Error fetching contents: {str(e)}"]

	# Parse initial response and get recursive structure
	try:
		initial_data = json.loads(api_response)
		if isinstance(initial_data, dict) and 'message' in initial_data:
			file_structure = f"Error: {initial_data['message']}"
		else:
			# Get the complete recursive structure
			structure_lines = get_recursive_contents(api_url)
			file_structure = "\n".join(structure_lines)
	except json.JSONDecodeError:
		file_structure = "Error: Invalid JSON response from API"
	except Exception as e:
		file_structure = f"Error: {str(e)}"

	return {
		"file_structure": file_structure
