      "type": "llm",
      "param": {
        "system": "You are an expert academic assistant. Read and understand the provided paper content, then answer the user's question based solely on the information in the paper. Always provide supporting evidence from the paper.",
        "user": "Paper content: {{#2.text#}}

Question: {{#1.question#}}

Please provide:
1. A comprehensive answer to the question based only on the paper content above.
2. The specific textual evidence from the paper that supports your answer. Include direct quotes when possible.

Format your response as:
ANSWER: [your answer here]
EVIDENCE: [supporting evidence from the paper here]"
      }
    },
    {
      "id": "4",
      "type": "code",
      "param": {
        "variables": [["llm_response", ["text", "3"]]],
        "outputs": [["answer", "string"], ["evidence", "string"]],
        "code": "def main(llm_response: str):
	# Parse the LLM response to extract answer and evidence
	answer = ""
	evidence = ""

	# Split by lines and parse
	lines = llm_response.split('\n')
	current_section = None

	for line in lines:
		line = line.strip()
		if line.startswith('ANSWER:'):
			current_section = 'answer'
			answer = line[7:].strip()
		elif line.startswith('EVIDENCE:'):
			current_section = 'evidence'
			evidence = line[9:].strip()
		elif current_section == 'answer' and line:
			answer += ' ' + line
		elif current_section == 'evidence' and line:
			evidence += ' ' + line

	# Fallback parsing if structured format wasn't followed
	if not answer or not evidence:
		if 'ANSWER:' in llm_response and 'EVIDENCE:' in llm_response:
			parts = llm_response.split('EVIDENCE:')
			answer_part = parts[0].replace('ANSWER:', '').strip()
			evidence_part = parts[1].strip()
			answer = answer_part
			evidence = evidence_part
		else:
			# If no clear separation, use the whole response as answer
			answer = llm_response
			evidence = "Evidence not clearly separated from answer."

	return {
		"answer": answer,
		"evidence": evidence
	}"
      }
    },
